"""Instance model: strict schema validation and exact semantics (contract 1.1.1).

An instance is the validated form of one request line.  All routing
arithmetic is kept exact with :class:`fractions.Fraction`.
"""

import re
from fractions import Fraction
from math import gcd

_NAME_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}\Z')
_METRICS = ('demand', 'link', 'ingress', 'egress')

# Field-specific numeric ranges of the public contract.
MAX_NODES = 12
MAX_EDGES = 32
MAX_COMMODITIES = 12
MAX_ROUTES = 3
MAX_ROUTE_WEIGHT = 8
MAX_ROUTE_WEIGHT_SUM = 8
MAX_DOMAINS = 14
MAX_SNAPSHOTS = 4
MAX_OBS_PER_SNAPSHOT = 96
MAX_OBS_TOTAL = 256
DEMAND_LIMIT = 10000
CAPACITY_LIMIT = 1000000
OBS_LIMIT = 1000000


class InvalidInstance(Exception):
    """The request violates the public contract."""


def is_name(x):
    """True for an ASCII name matching [A-Za-z][A-Za-z0-9_-]{0,31}."""
    return type(x) is str and _NAME_RE.match(x) is not None


def is_int(x):
    """True for a JSON integer (booleans are excluded)."""
    return type(x) is int


def _req_field(obj, key):
    if key not in obj:
        raise InvalidInstance()
    return obj[key]


class Edge(object):
    __slots__ = ('id', 'source', 'target', 'capacity')

    def __init__(self, eid, source, target, capacity):
        self.id = eid
        self.source = source
        self.target = target
        self.capacity = capacity


class Route(object):
    __slots__ = ('edges', 'weight', 'edge_set')

    def __init__(self, edges, weight):
        self.edges = edges
        self.weight = weight
        self.edge_set = frozenset(edges)


class Commodity(object):
    __slots__ = ('id', 'source', 'target', 'routes', 'total_weight')

    def __init__(self, cid, source, target, routes, total_weight):
        self.id = cid
        self.source = source
        self.target = target
        self.routes = routes
        self.total_weight = total_weight


class Observation(object):
    __slots__ = ('id', 'metric', 'target', 'lower', 'upper', 'domain')

    def __init__(self, oid, metric, target, lower, upper, domain):
        self.id = oid
        self.metric = metric
        self.target = target
        self.lower = lower
        self.upper = upper
        self.domain = domain


class Snapshot(object):
    __slots__ = ('id', 'bounds', 'controller', 'tolerance', 'observations')

    def __init__(self, sid, bounds, controller, tolerance, observations):
        self.id = sid
        self.bounds = bounds
        self.controller = controller
        self.tolerance = tolerance
        self.observations = observations


class Instance(object):
    __slots__ = ('id', 'nodes', 'edges', 'commodities', 'domains', 'max_faults',
                 'snapshots', 'node_set', 'edge_index', 'commodity_index',
                 'domain_index', 'ingress_indices', 'egress_indices',
                 'edge_coeff')

    def __init__(self):
        self.id = None

    # -- semantic helpers -------------------------------------------------

    def observed_domains(self):
        """Domains that own at least one observation, in input order."""
        seen = set()
        out = []
        for snap in self.snapshots:
            for obs in snap.observations:
                d = obs.domain
                if d is not None and d not in seen:
                    seen.add(d)
                    out.append(d)
        return out

    def compute_edge_coeff(self):
        """For each edge index: (scale, coeffs) with load = coeffs . q / scale.

        ``coeffs[c]`` is the integer number of scale-units contributed by one
        unit of demand of commodity ``c``; the scale is the least common
        denominator of the edge's rational contributions.
        """
        nc = len(self.commodities)
        out = []
        for edge in self.edges:
            fr = [Fraction(0)] * nc
            for ci, com in enumerate(self.commodities):
                total = Fraction(0)
                for route in com.routes:
                    if edge.id in route.edge_set:
                        total += Fraction(route.weight, com.total_weight)
                fr[ci] = total
            scale = 1
            for value in fr:
                if value:
                    scale = scale * value.denominator // gcd(scale, value.denominator)
            out.append((scale, [int(value * scale) for value in fr]))
        self.edge_coeff = out
        return out

    def ingress_sum(self, demands, node):
        total = 0
        for ci, com in enumerate(self.commodities):
            if com.source == node:
                total += demands[ci]
        return total

    def egress_sum(self, demands, node):
        total = 0
        for ci, com in enumerate(self.commodities):
            if com.target == node:
                total += demands[ci]
        return total

    def edge_loads(self, demands):
        """Exact rational loads for one snapshot's demand vector."""
        loads = []
        for ei in range(len(self.edges)):
            scale, coeffs = self.edge_coeff[ei]
            total = 0
            for ci, coef in enumerate(coeffs):
                if coef:
                    total += coef * demands[ci]
            loads.append(Fraction(total, scale))
        return loads

    def true_value(self, obs, demands, loads):
        """True value of one observation for one snapshot's demands."""
        metric = obs.metric
        if metric == 'demand':
            return demands[self.commodity_index[obs.target]]
        if metric == 'link':
            return loads[self.edge_index[obs.target]]
        if metric == 'ingress':
            return self.ingress_sum(demands, obs.target)
        return self.egress_sum(demands, obs.target)


def parse_request(obj):
    """Validate one decoded JSON request and build an :class:`Instance`."""
    inst = Instance()
    if type(obj) is not dict:
        raise InvalidInstance()

    version = _req_field(obj, 'version')
    if not is_int(version) or version != 1:
        raise InvalidInstance()

    rid = _req_field(obj, 'id')
    if not is_name(rid):
        raise InvalidInstance()
    inst.id = rid

    # nodes -------------------------------------------------------------
    nodes = _req_field(obj, 'nodes')
    if type(nodes) is not list or not (2 <= len(nodes) <= MAX_NODES):
        raise InvalidInstance()
    for node in nodes:
        if not is_name(node):
            raise InvalidInstance()
    if len(set(nodes)) != len(nodes):
        raise InvalidInstance()
    inst.nodes = nodes
    inst.node_set = frozenset(nodes)

    # edges -------------------------------------------------------------
    raw_edges = _req_field(obj, 'edges')
    if type(raw_edges) is not list or len(raw_edges) > MAX_EDGES:
        raise InvalidInstance()
    edges = []
    edge_index = {}
    for raw in raw_edges:
        if type(raw) is not dict:
            raise InvalidInstance()
        eid = _req_field(raw, 'id')
        source = _req_field(raw, 'source')
        target = _req_field(raw, 'target')
        capacity = _req_field(raw, 'capacity')
        if not is_name(eid):
            raise InvalidInstance()
        if eid in edge_index:
            raise InvalidInstance()
        if type(source) is not str or source not in inst.node_set:
            raise InvalidInstance()
        if type(target) is not str or target not in inst.node_set:
            raise InvalidInstance()
        if source == target:
            raise InvalidInstance()
        if not is_int(capacity) or not (0 <= capacity <= CAPACITY_LIMIT):
            raise InvalidInstance()
        edge_index[eid] = len(edges)
        edges.append(Edge(eid, source, target, capacity))
    inst.edges = edges
    inst.edge_index = edge_index

    # commodities --------------------------------------------------------
    raw_comms = _req_field(obj, 'commodities')
    if type(raw_comms) is not list or len(raw_comms) > MAX_COMMODITIES:
        raise InvalidInstance()
    commodities = []
    commodity_index = {}
    pairs = set()
    for raw in raw_comms:
        if type(raw) is not dict:
            raise InvalidInstance()
        cid = _req_field(raw, 'id')
        source = _req_field(raw, 'source')
        target = _req_field(raw, 'target')
        raw_routes = _req_field(raw, 'routes')
        if not is_name(cid):
            raise InvalidInstance()
        if cid in commodity_index:
            raise InvalidInstance()
        if type(source) is not str or source not in inst.node_set:
            raise InvalidInstance()
        if type(target) is not str or target not in inst.node_set:
            raise InvalidInstance()
        if source == target:
            raise InvalidInstance()
        if (source, target) in pairs:
            raise InvalidInstance()
        pairs.add((source, target))
        if type(raw_routes) is not list or not (1 <= len(raw_routes) <= MAX_ROUTES):
            raise InvalidInstance()
        routes = []
        weight_sum = 0
        for raw_route in raw_routes:
            if type(raw_route) is not dict:
                raise InvalidInstance()
            edge_ids = _req_field(raw_route, 'edges')
            weight = _req_field(raw_route, 'weight')
            if type(edge_ids) is not list or len(edge_ids) == 0:
                raise InvalidInstance()
            if not is_int(weight) or not (1 <= weight <= MAX_ROUTE_WEIGHT):
                raise InvalidInstance()
            current = source
            visited = [source]
            for eid in edge_ids:
                if type(eid) is not str or eid not in edge_index:
                    raise InvalidInstance()
                edge = edges[edge_index[eid]]
                if edge.source != current:
                    raise InvalidInstance()
                current = edge.target
                visited.append(current)
            if current != target:
                raise InvalidInstance()
            if len(set(visited)) != len(visited):
                raise InvalidInstance()
            routes.append(Route(edge_ids, weight))
            weight_sum += weight
        if weight_sum > MAX_ROUTE_WEIGHT_SUM:
            raise InvalidInstance()
        commodity_index[cid] = len(commodities)
        commodities.append(Commodity(cid, source, target, routes, weight_sum))
    inst.commodities = commodities
    inst.commodity_index = commodity_index

    # domains / fault budget ---------------------------------------------
    raw_domains = _req_field(obj, 'domains')
    if type(raw_domains) is not list or len(raw_domains) > MAX_DOMAINS:
        raise InvalidInstance()
    for domain in raw_domains:
        if not is_name(domain):
            raise InvalidInstance()
    if len(set(raw_domains)) != len(raw_domains):
        raise InvalidInstance()
    inst.domains = raw_domains
    domain_set = frozenset(raw_domains)
    max_faults = _req_field(obj, 'max_faults')
    if not is_int(max_faults) or not (0 <= max_faults <= len(raw_domains)):
        raise InvalidInstance()
    inst.max_faults = max_faults

    # snapshots -----------------------------------------------------------
    raw_snaps = _req_field(obj, 'snapshots')
    if type(raw_snaps) is not list or not (1 <= len(raw_snaps) <= MAX_SNAPSHOTS):
        raise InvalidInstance()
    ncom = len(commodities)
    snapshots = []
    snap_ids = set()
    total_obs = 0
    for raw in raw_snaps:
        if type(raw) is not dict:
            raise InvalidInstance()
        sid = _req_field(raw, 'id')
        if not is_name(sid) or sid in snap_ids:
            raise InvalidInstance()
        snap_ids.add(sid)
        raw_bounds = _req_field(raw, 'bounds')
        if type(raw_bounds) is not list or len(raw_bounds) != ncom:
            raise InvalidInstance()
        bounds = []
        for pair in raw_bounds:
            if type(pair) is not list or len(pair) != 2:
                raise InvalidInstance()
            lo = pair[0]
            hi = pair[1]
            if not is_int(lo) or not is_int(hi):
                raise InvalidInstance()
            if not (0 <= lo <= hi <= DEMAND_LIMIT):
                raise InvalidInstance()
            bounds.append((lo, hi))
        controller = _req_field(raw, 'controller')
        if type(controller) is not list or len(controller) != ncom:
            raise InvalidInstance()
        for value in controller:
            if not is_int(value) or not (0 <= value <= DEMAND_LIMIT):
                raise InvalidInstance()
        tolerance = _req_field(raw, 'tolerance')
        if not is_int(tolerance) or not (0 <= tolerance <= DEMAND_LIMIT):
            raise InvalidInstance()
        raw_obs = _req_field(raw, 'observations')
        if type(raw_obs) is not list or len(raw_obs) > MAX_OBS_PER_SNAPSHOT:
            raise InvalidInstance()
        total_obs += len(raw_obs)
        observations = []
        obs_ids = set()
        for raw_obs_item in raw_obs:
            if type(raw_obs_item) is not dict:
                raise InvalidInstance()
            oid = _req_field(raw_obs_item, 'id')
            if not is_name(oid) or oid in obs_ids:
                raise InvalidInstance()
            obs_ids.add(oid)
            metric = _req_field(raw_obs_item, 'metric')
            if type(metric) is not str or metric not in _METRICS:
                raise InvalidInstance()
            target = _req_field(raw_obs_item, 'target')
            if not is_name(target):
                raise InvalidInstance()
            lower = _req_field(raw_obs_item, 'lower')
            upper = _req_field(raw_obs_item, 'upper')
            if not is_int(lower) or not is_int(upper):
                raise InvalidInstance()
            if not (-OBS_LIMIT <= lower <= upper <= OBS_LIMIT):
                raise InvalidInstance()
            domain = _req_field(raw_obs_item, 'domain')
            if domain is not None:
                if type(domain) is not str or domain not in domain_set:
                    raise InvalidInstance()
            if metric == 'demand':
                if target not in commodity_index:
                    raise InvalidInstance()
            elif metric == 'link':
                if target not in edge_index:
                    raise InvalidInstance()
            else:
                if target not in inst.node_set:
                    raise InvalidInstance()
            observations.append(Observation(oid, metric, target, lower, upper, domain))
        snapshots.append(Snapshot(sid, bounds, controller, tolerance, observations))
    if total_obs > MAX_OBS_TOTAL:
        raise InvalidInstance()
    inst.snapshots = snapshots

    # derived lookup tables ----------------------------------------------
    inst.domain_index = {}
    for di, domain in enumerate(inst.domains):
        inst.domain_index[domain] = di
    inst.ingress_indices = {}
    inst.egress_indices = {}
    for node in inst.nodes:
        inst.ingress_indices[node] = [ci for ci, com in enumerate(commodities)
                                      if com.source == node]
        inst.egress_indices[node] = [ci for ci, com in enumerate(commodities)
                                     if com.target == node]
    inst.compute_edge_coeff()
    return inst
